'use strict';
/**
 * Golden: with the class round off (its own switch off, or on without its parent), the teacher's report page and a
 * Challenge run are BYTE-IDENTICAL to the code path before the round existed. The snapshots in
 * __snapshots__/class-round-golden.test.js.snap were written by this file on the base branch, before any round
 * code was added, and are never regenerated by the round's change.
 *
 * Real routes on an ephemeral port, the real report data core, the real tokens and the real Challenge service.
 * Faked: Supabase (an in-memory client that applies filters), the event logger, R2 and the speech/LLM clients.
 */
jest.mock('../../../shared/config/supabase', () => ({}));
jest.mock('../../../shared/utils/logger', () => ({ logToFile: jest.fn(), logError: jest.fn(), logWarn: jest.fn() }));
jest.mock('../../../shared/utils/structured-logger', () => ({ logEvent: jest.fn(), getCurrentCorrelationId: () => null }));
jest.mock('../../../shared/utils/html-to-pdf', () => ({ htmlToPdf: jest.fn(async () => Buffer.from('%PDF-1.4 fake')) }));
jest.mock('../../../shared/storage/r2', () => ({
  getPresignedUploadUrl: jest.fn(), headObject: jest.fn(), downloadFromR2: jest.fn(), getPresignedUrl: jest.fn(),
  buildR2PublicUrl: jest.fn((k) => `https://r2.test/${k}`), uploadBuffer: jest.fn(), presignKey: jest.fn(async () => null),
  deleteAudio: jest.fn(), deleteKey: jest.fn(), listKeys: jest.fn(async () => []),
}));
jest.mock('../../../shared/services/audio.service', () => ({ transcribe: jest.fn() }));
jest.mock('../../../shared/services/tts', () => ({ synthesize: jest.fn() }));
jest.mock('../../../shared/services/llm-client', () => ({ getClient: () => ({ chat: { completions: { create: jest.fn() } } }) }));
jest.mock('../../../shared/services/cache/railway-redis.service', () => {
  const store = new Map();
  return { isAvailable: () => true, get: async (k) => (store.has(k) ? store.get(k) : null), setNX: async (k, v) => { if (store.has(k)) return false; store.set(k, v); return true; } };
});
jest.mock('openchemlib', () => require('../../../../tests/__mocks__/openchemlib.js'));

const crypto = require('crypto');
const express = require('express');
// The page embeds its fonts as base64 (~200 KB), so the snapshot holds the page's sha256 and length, not the page.
const digest = (html) => ({ sha256: crypto.createHash('sha256').update(html).digest('hex'), bytes: Buffer.byteLength(html) });
const { makeFake } = require('./fake-supabase');

const FIXED_NOW = Date.parse('2026-10-15T09:30:00Z');
const TEACHER = '11111111-1111-4111-8111-111111111111';
const QUIZ = '22222222-2222-4222-8222-222222222222';
const SC = '33333333-3333-4333-8333-333333333333';
const LIST = 'a0000000-0000-4000-8000-00000000003b';
const CLASS = 'c0000000-0000-4000-8000-0000000000c1';
const SCHOOL = 'd0000000-0000-4000-8000-0000000000d1';
const SESSION = '66666666-6666-4666-8666-666666666666';
const kid = (n) => `b0000000-0000-4000-8000-0000000000${String(n).padStart(2, '0')}`;
const at = (h) => new Date(FIXED_NOW - h * 3600000).toISOString();

// Three ways the round is "off": no switch rows, its own switch off, its own switch on with the parent off.
const OFF_CASES = {
  none: [],
  own_off: [{ key: 'web_quiz_class_round', value: false }, { key: 'web_quiz_challenge_v2', value: true }],
  parent_off: [{ key: 'web_quiz_class_round', value: true }, { key: 'web_quiz_challenge_v2', value: false }],
};

let DB;
function seed(settings) {
  DB = {
    app_settings: [{ key: 'web_quiz_challenge', value: true }, ...settings],
    users: [{ id: TEACHER, preferred_language: 'en' }],
    quizzes: [{ id: QUIZ, teacher_id: TEACHER, topic: 'Plants', subject: 'science', grade: '3', language: 'en', quiz_source: 'transcript', status: 'report_sent',
      list_id: null, created_at: at(30), meta: { share_code_id: SC, student_message: 'Our quiz is ready! Tap: https://portal.example.test/q/AB12CD' } }],
    quiz_share_codes: [{ id: SC, code: 'AB12CD', quiz_id: QUIZ, teacher_user_id: TEACHER, invited_by_student_id: null, active: true, expires_at: null, language: 'en', created_at: at(30) }],
    student_lists: [{ id: LIST, class_name: '3', section: 'B', user_id: TEACHER, is_active: true }],
    students: [1, 2, 3].map((r) => ({ id: kid(r), list_id: LIST, roll_number: r, student_name: `Kid${r} Testwala`, student_name_urdu: null, is_active: true })),
    quiz_sessions: [{ id: SESSION, quiz_id: QUIZ, share_code_id: SC, student_id: kid(1), student_name: 'Kid1 Testwala', user_id: null, status: 'completed',
      correct_answers: 3, total_questions_answered: 4, completed_at: at(20), created_at: at(20.1), invited_by_student_id: null, device_ref: 'd1' }],
    quiz_questions: [],
    quiz_answers: [],
    // A class with an open draw this term: with the round off, none of this may show anywhere.
    schools: [{ id: SCHOOL, name: 'School A', region: 'Sector One', is_active: true, is_probable_test: false }],
    classes: [{ id: CLASS, school_id: SCHOOL, grade_code: 'grade_3', section: 'B', is_active: true }],
    class_teachers: [{ id: 'ct1', class_id: CLASS, teacher_user_id: TEACHER, is_class_teacher: true, is_active: true }],
    class_enrollments: [1, 2, 3].map((r) => ({ id: `e${r}`, class_id: CLASS, student_id: kid(r), roll_number: r, is_active: true })),
    class_round_draws: [{ id: 'e0000000-0000-4000-8000-0000000000e1', round: '0123456789abcdef', term_code: '2026-27b', class_id: CLASS, stratum: 'Sector One|G23',
      roster_k: 3, drawn_at: at(48), started_at: null, ran_at: null, finished_at: null, children_present: null, children_played: null, state: null }],
    web_quiz_challenge_runs: [],
  };
  const fake = makeFake(DB);
  Object.assign(require('../../../shared/config/supabase'), { from: fake.from, rpc: fake.rpc });
}

describe.each(Object.keys(OFF_CASES))('round off (%s): the report page is byte-identical', (name) => {
  let server; let base; let Token;
  beforeEach(async () => {
    jest.resetModules();
    jest.spyOn(Date, 'now').mockReturnValue(FIXED_NOW);
    process.env.INTERNAL_API_KEY = 'test-key';
    delete process.env.WEB_QUIZ_TOKEN_SECRET;
    seed(OFF_CASES[name]);
    Token = require('../../../shared/services/quiz/teacher-report-token');
    const app = express();
    app.use('/api/internal/tr', require('../../../shared/routes/teacher-report-internal.routes'));
    await new Promise((r) => { server = app.listen(0, '127.0.0.1', r); });
    base = `http://127.0.0.1:${server.address().port}/api/internal/tr`;
  });
  afterEach(async () => { jest.restoreAllMocks(); await new Promise((r) => server.close(r)); });
  const get = (p) => fetch(`${base}${p}`, { headers: { 'x-api-key': 'test-key' }, redirect: 'manual' });

  test.each([['class tab en', ''], ['class tab ur', '?lang=ur'], ['class tab explicit', '?tab=class']])('%s', async (_label, q) => {
    const res = await get(`/page/${Token.signTeacherReport({ teacherId: TEACHER, now: FIXED_NOW })}${q}`);
    expect(res.status).toBe(200);
    expect(digest(await res.text())).toMatchSnapshot('report class tab');
  });

  test('quiz tab', async () => {
    const res = await get(`/page/${Token.signTeacherReport({ teacherId: TEACHER, quizId: QUIZ, now: FIXED_NOW })}`);
    expect(res.status).toBe(200);
    expect(digest(await res.text())).toMatchSnapshot('report quiz tab');
  });
});

describe.each(Object.keys(OFF_CASES))('round off (%s): a Challenge run is byte-identical', (name) => {
  let T; let Ch; let Bank;
  beforeEach(() => {
    jest.resetModules();
    process.env.INTERNAL_API_KEY = 'test-internal-key';
    seed(OFF_CASES[name]);
    T = require('../../../shared/services/quiz/web-quiz-token');
    Ch = require('../../../shared/services/quiz/web-quiz-challenge');
    Bank = require('../../../shared/services/child-test/item-bank');
    Ch.__reset();
  });

  test('exercise payload, the challenge token claims, and the stored row', async () => {
    const st = T.signSession({ sessionId: SESSION, deviceRef: 'DeviceRefGolden_000001', shareCodeId: SC });
    const out = await Ch.exercise(st, 'bigger', { lang: 'en' });
    const claims = T.verify(out.ct, 'c');
    expect(Object.keys(claims).sort()).toMatchSnapshot('challenge token claim keys');
    expect({ ...claims, r: '<run>', exp: '<exp>' }).toMatchSnapshot('challenge token claims');
    expect({ ...out, ct: '<ct>' }).toMatchSnapshot('bigger exercise payload');
    const spec = Bank.getTaskSpec({ grade: 3, set: 'A', task: 'ma.discrimination' });
    const taps = out.items.map((it, i) => ({ i, pick: Math.max(it.a, it.b), ms: 2000 }));
    await Ch.submit({ ct: out.ct, taps, ms: 20000 }, { now: Date.now() + 30000 });
    expect(spec.items.length).toBeGreaterThan(0);
    const row = DB.web_quiz_challenge_runs[0];
    expect(Object.keys(row).sort()).toMatchSnapshot('stored row columns');
    expect({ ...row, id: '<run>', created_at: '<t>', scored_at: '<t>' }).toMatchSnapshot('stored row');
  });
});
